import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello} from './kit';
// DINERO 28-nov 12h "La cuenta segura es de ellos". 2.5D con codigo: volumen (Vol), 3 capas con parallax, giro leve, sombras en el suelo.
// Protagonista que viaja: el celular de Roberto y su dinero como rio de monedas oro. Estafador solo en silueta con contraluz rojo.
export const SUBS={arriba:860,size:84,acento:'#FFC83D'};
type C=[string,string,string];
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const ql=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const pop=(s:number,a:number,d=.28)=>interpolate(s,[a,a+d],[0,1],{...clamp,easing:Easing.out(Easing.back(2))});
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}A${r} ${r} 0 0 1 ${x+w} ${y+r}V${y+h-r}A${r} ${r} 0 0 1 ${x+w-r} ${y+h}H${x+r}A${r} ${r} 0 0 1 ${x} ${y+h-r}V${y+r}A${r} ${r} 0 0 1 ${x+r} ${y}Z`;
// Capsula cerrada: dedos, brazos y cuellos con volumen (nunca trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const SK:C=['#f6d9b8','#d99d6c','#8c5530'],SKV:C=['#fbe6d4','#ecb898','#a86a4c'],DK:C=['#5a2030','#240a12','#07000a'];
const SH:C=['#d3ebff','#4FA3FF','#1a5aa8'],GOLD:C=['#FFF2B8','#FFC83D','#9A6410'],PH:C=['#8a93a3','#262b36','#07090d'];
const RD:C=['#ffb0b0','#FF4D4D','#8a1010'],GR:C=['#c8ffe0','#22D37A','#0a6a3a'];
const Vol:React.FC<{id:string;d:string;c:C;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b3' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='3'/></filter>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='coinG' cx='.35' cy='.3'><stop stopColor='#FFF6C8'/><stop offset='.5' stopColor='#FFC83D'/><stop offset='1' stopColor='#B97A12'/></radialGradient>
 <linearGradient id='plata' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#ffffff'/><stop offset='.5' stopColor='#9aa4b2'/><stop offset='1' stopColor='#eef2f7'/></linearGradient>
 <linearGradient id='vidrio' x1='0' y1='0' x2='1' y2='0'><stop stopColor='#cfeeff' stopOpacity='.55'/><stop offset='.5' stopColor='#6aa8d8' stopOpacity='.1'/><stop offset='1' stopColor='#cfeeff' stopOpacity='.45'/></linearGradient>
 <radialGradient id='hole' cx='.5' cy='.5'><stop stopColor='#000'/><stop offset='.72' stopColor='#12000a'/><stop offset='1' stopColor='#ff4d4d'/></radialGradient>
 <linearGradient id='bigote' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#f1f1f3'/><stop offset='.6' stopColor='#a3a5ad'/><stop offset='1' stopColor='#60626b'/></linearGradient>
 <linearGradient id='madera' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#c88a4a'/><stop offset='.5' stopColor='#8a5424'/><stop offset='1' stopColor='#4a2a10'/></linearGradient>
 <linearGradient id='pantG' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#17408a'/><stop offset='1' stopColor='#050d1f'/></linearGradient>
 <linearGradient id='escudoG' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#9fd0ff'/><stop offset='.5' stopColor='#2f7de0'/><stop offset='1' stopColor='#12306a'/></linearGradient>
 <radialGradient id='rojoLuz'><stop stopColor='#ff4d4d' stopOpacity='.8'/><stop offset='1' stopColor='#ff4d4d' stopOpacity='0'/></radialGradient>
 <radialGradient id='verdeLuz'><stop stopColor='#22D37A' stopOpacity='.8'/><stop offset='1' stopColor='#22D37A' stopOpacity='0'/></radialGradient>
 <radialGradient id='oroLuz'><stop stopColor='#FFC83D' stopOpacity='.85'/><stop offset='1' stopColor='#FFC83D' stopOpacity='0'/></radialGradient>
 <radialGradient id='calidaLuz'><stop stopColor='#FF9A3C' stopOpacity='.75'/><stop offset='1' stopColor='#FF9A3C' stopOpacity='0'/></radialGradient>
 <linearGradient id='mascG' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#fffaf0'/><stop offset='.6' stopColor='#f1d9bc'/><stop offset='1' stopColor='#b48a62'/></linearGradient>
 <linearGradient id='sacoG' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#d8b078'/><stop offset='.6' stopColor='#9a6c34'/><stop offset='1' stopColor='#4a2c10'/></linearGradient>
 </defs>;
const Tx:React.FC<{x:number;y:number;t:string;size:number;c?:string;w?:number;a?:'start'|'middle'|'end';o?:number;sk?:string}>=({x,y,t,size,c='#fff',w=900,a='middle',o=1,sk})=>
 <text x={x} y={y} textAnchor={a} fontFamily={FONT} fontWeight={w} fontSize={size} fill={c} opacity={o} stroke={sk} strokeWidth={sk?size*.09:0} paintOrder='stroke' strokeLinejoin='round'>{t}</text>;
const Pill:React.FC<{x:number;y:number;w:number;h:number;c:string;t:string;size:number;tc?:string;o?:number;fill?:string;k?:number}>=({x,y,w,h,c,t,size,tc='#fff',o=1,fill='#0a1020',k=1})=>
 <g opacity={o} transform={`translate(${x} ${y}) scale(${k})`}><rect x={-w/2} y={-h/2+10} width={w} height={h} rx={h/3} fill='#000' opacity={.4} filter='url(#b6)'/><rect x={-w/2} y={-h/2} width={w} height={h} rx={h/3} fill={fill} stroke={c} strokeWidth={6}/><Tx x={0} y={size*.35} t={t} size={size} c={tc}/></g>;
// ---------- Moneda y rio de monedas ----------
const Coin:React.FC<{x:number;y:number;r?:number;a?:number;o?:number;sh?:boolean}>=({x,y,r=34,a=0,o=1,sh=false})=>{const w=Math.max(.14,Math.abs(Math.cos(a)))*r;
 return <g transform={`translate(${x} ${y})`} opacity={o}>
  {sh&&<ellipse cx={6} cy={r*.95} rx={w*1.1} ry={r*.22} fill='#000' opacity={.3} filter='url(#b6)'/>}
  <ellipse rx={w+r*.1} ry={r} fill='#8a5a0a'/>
  <ellipse rx={w} ry={r} fill='url(#coinG)' stroke='#8a5a0a' strokeWidth={2}/>
  <ellipse rx={w*.72} ry={r*.72} fill='none' stroke='#b57a14' strokeWidth={r*.09}/>
  {w>r*.45&&<text y={r*.3} textAnchor='middle' fontFamily={FONT} fontWeight={900} fontSize={r*.95} fill='#a8700e' transform={`scale(${w/r} 1)`}>$</text>}
  <ellipse cx={-w*.38} cy={-r*.42} rx={Math.max(2,w*.16)} ry={r*.26} fill='#fff' opacity={.7} transform={`rotate(25 ${-w*.38} ${-r*.42})`}/>
 </g>;};
// ---------- Celular ----------
const Phone:React.FC<{id:string;x?:number;y?:number;k?:number;rot?:number;glow?:string;gl?:number;sh?:boolean;children?:React.ReactNode}>=({id,x=0,y=0,k=1,rot=0,glow='#22D37A',gl=.5,sh=true,children})=><g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
 {sh&&<ellipse cx={34} cy={410} rx={210} ry={34} fill='#000' opacity={.38} filter='url(#b18)'/>}
 {gl>0&&<ellipse rx={300} ry={470} fill={glow} opacity={gl*.4} filter='url(#b40)'/>}
 <Vol id={id+'b'} d={rr(-182,-372,364,744,58)} c={PH} sw={70} o={22}/>
 <path d={rr(-182,-372,364,744,58)} fill='none' stroke='url(#plata)' strokeWidth={9}/>
 <defs><clipPath id={id+'s'}><path d={rr(-158,-348,316,696,40)}/></clipPath></defs>
 <g clipPath={`url(#${id}s)`}><rect x={-158} y={-348} width={316} height={696} fill='#06101f'/>{children}<path d='M-158 -348L-30 -348L-158 110Z' fill='#fff' opacity={.07}/></g>
 <rect x={-42} y={-340} width={84} height={14} rx={7} fill='#05070b'/>
 <rect x={182} y={-120} width={8} height={96} rx={3} fill='url(#plata)'/>
 </g>;
const Shield:React.FC<{x:number;y:number;k?:number;check?:boolean;o?:number}>=({x,y,k=1,check=true,o=1})=><g transform={`translate(${x} ${y}) scale(${k})`} opacity={o}>
 <path d='M0 -80L64 -56V10C64 56 28 84 0 100C-28 84 -64 56 -64 10V-56Z' fill='url(#escudoG)' stroke='#d6ebff' strokeWidth={5}/>
 <path d='M0 -62L48 -44V8C48 44 22 66 0 80Z' fill='#fff' opacity={.12}/>
 {check&&<path d='M-26 8L-6 30L30 -18' stroke='#fff' strokeWidth={11} fill='none' strokeLinecap='round' strokeLinejoin='round'/>}
 <Brillo2 x={-26} y={-44} rx={10} ry={22} r={20} o={.6}/>
 </g>;
const Handset:React.FC<{x:number;y:number;rot?:number;k?:number}>=({x,y,rot=0,k=1})=><path transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`} d='M-26 8C-26 -10 -12 -20 0 -20C12 -20 26 -10 26 8L14 14L10 0C4 -5 -4 -5 -10 0L-14 14Z' fill='#fff'/>;
const LlamScr:React.FC<{s:number;texto?:string;sub?:string;unk?:boolean;press?:number}>=({s,texto='BANCO',sub='llamando…',unk=false,press=0})=><g>
 <rect x={-158} y={-348} width={316} height={696} fill='url(#pantG)'/>
 <circle cy={-140} r={112+Math.sin(s*9)*7} fill={unk?'#FF4D4D':'#22D37A'} opacity={.2}/>
 {!unk&&<Shield x={0} y={-140} k={1.05} check={false}/>}
 {unk&&<><circle cy={-140} r={74} fill='#2a0a14' stroke='#FF4D4D' strokeWidth={6}/><Tx x={0} y={-108} t='?' size={110} c='#FF4D4D'/></>}
 <Tx x={0} y={-6} t={texto} size={unk?44:70} c={unk?'#ffb0b0':'#fff'}/><Tx x={0} y={44} t={sub} size={28} c='#9fc4ff' w={600}/>
 <circle cx={-86} cy={250} r={46} fill='#FF4D4D' transform={`scale(${1-press*.1})`} style={{transformOrigin:'-86px 250px'}}/><Handset x={-86} y={250} rot={135} k={1.1}/>
 <circle cx={86} cy={250} r={52+Math.sin(s*9)*5} fill='#22D37A' opacity={.3}/><circle cx={86} cy={250} r={46} fill='#22D37A'/><Handset x={86} y={250} k={1.1}/>
 </g>;
// ---------- Manos con volumen (union de capsulas, nunca trazos sueltos) ----------
const Mano:React.FC<{id:string;x?:number;y?:number;rot?:number;k?:number;dob?:number;pul?:number;c?:C;anillo?:boolean;fl?:boolean}>=({id,x=0,y=0,rot=0,k=1,dob=0,pul=0,c=SK,anillo=true,fl=false})=>{
 const F:[number,number,number,number,number][]=[[-52,-62,-8,.8,34],[-18,-70,-2,1,35],[17,-68,3,.93,33],[49,-60,9,.7,29]];
 const fg=F.map(([bx,by,a,lf,w])=>{const len=150*lf*(1-.5*dob),an=(a-90)*Math.PI/180;return{bx,by,w,a,ex:bx+Math.cos(an)*len,ey:by+Math.sin(an)*len+dob*50};});
 const th={x1:-60,y1:40,x2:-132-pul*10,y2:-14-pul*30+dob*20,w:44};
 const d='M-76 -58C-84 10 -80 70 -52 102C-22 130 34 130 62 102C88 70 86 10 76 -58Z'+fg.map(f=>caps(f.bx,f.by,f.ex,f.ey,f.w)).join('')+caps(th.x1,th.y1,th.x2,th.y2,th.w);
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${fl?-k:k} ${k})`}>
  <Vol id={id} d={d} c={c} sw={44} o={13}/>
  {fg.map((f,j)=>{const dx=f.ex-f.bx,dy=f.ey-f.by,L=Math.hypot(dx,dy)||1,ux=dx/L,uy=dy/L;
   return <g key={j}>
    <path d={caps(f.bx,f.by,f.ex,f.ey,f.w)} fill='none' stroke={c[2]} strokeWidth={3} opacity={.5}/>
    {[.38,.64].map((t,i)=>{const px=f.bx+dx*t,py=f.by+dy*t;return <path key={i} d={`M${px-uy*f.w*.3} ${py+ux*f.w*.3}Q${px+ux*3} ${py+uy*3} ${px+uy*f.w*.3} ${py-ux*f.w*.3}`} stroke={c[2]} strokeWidth={3.5} fill='none' opacity={.55}/>;})}
    <ellipse cx={f.ex-ux*17} cy={f.ey-uy*17} rx={f.w*.3} ry={13} transform={`rotate(${f.a} ${f.ex-ux*17} ${f.ey-uy*17})`} fill='#ffeee4' opacity={.85} stroke={c[2]} strokeWidth={1.5}/>
    {anillo&&j===2&&<path d={`M${f.bx+dx*.42-uy*f.w*.5} ${f.by+dy*.42+ux*f.w*.5}L${f.bx+dx*.42+uy*f.w*.5} ${f.by+dy*.42-ux*f.w*.5}`} stroke='#f2d36b' strokeWidth={9} strokeLinecap='round'/>}
   </g>;})}
  {[-52,-18,17,49].map((kx,j)=><ellipse key={j} cx={kx} cy={-56} rx={14} ry={9} fill={c[2]} opacity={.2}/>)}
  <ellipse cx={th.x2+10} cy={th.y2+8} rx={14} ry={11} fill='#ffeee4' opacity={.85} stroke={c[2]} strokeWidth={1.5}/>
 </g>;};
// Pulgar grande que presiona (visto desde arriba, con una, pliegue y mano atras).
const Pulgar:React.FC<{id:string;x:number;y:number;k?:number;rot?:number;c?:C;pres?:number}>=({id,x,y,k=1,rot=0,c=SK,pres=0})=><g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k*(1-pres*.07)})`}>
 <ellipse cx={30} cy={40} rx={80} ry={26} fill='#000' opacity={.25} filter='url(#b18)'/>
 <Vol id={id} d={caps(0,700,0,0,118)+'M-140 760C-150 620 -90 560 0 560C90 560 150 620 140 760Z'} c={c} sw={60} o={18}/>
 <path d={rr(-34,10,68,92,26)} fill='#ffe9de' stroke={c[2]} strokeWidth={2.5} opacity={.92}/><Brillo2 x={-12} y={34} rx={8} ry={24} r={10} o={.6}/>
 <path d='M-44 240Q0 258 44 240M-40 262Q0 280 40 262' stroke={c[2]} strokeWidth={4} fill='none' opacity={.5}/>
 </g>;
// Dedos que sujetan el celular por el borde derecho (con el anillo de casado).
const AgarreDedos:React.FC<{id:string;c?:C}>=({id,c=SK})=><g>
 {[-110,-20,70].map((y,j)=><g key={j}>
  <Vol id={id+j} d={caps(300,y,150,y+(j-1)*10,48)} c={c} sw={30} o={9}/>
  <ellipse cx={162} cy={y+(j-1)*10} rx={14} ry={19} fill='#ffeee4' opacity={.85} stroke={c[2]} strokeWidth={1.5}/>
  {j===1&&<><path d='M232 -46V6' stroke='#f2d36b' strokeWidth={9} strokeLinecap='round'/><path d='M231 -40V-8' stroke='#fff7c0' strokeWidth={2.5}/></>}
 </g>)}
 <Vol id={id+'a'} d={caps(330,160,300,-40,110)} c={c} sw={50} o={14}/>
 <Vol id={id+'m'} d={caps(330,200,400,520,150)} c={SH} sw={60} o={18}/>
 </g>;
// ---------- Personas (Roberto 58 anos y los abuelos) ----------
type PM='c'|'w'|'d'|'r'|'s'|'o';
const BR:Record<PM,number[]>={c:[-48,-62,-46],w:[-72,-76,-40],d:[-38,-50,-54],r:[-58,-78,-56],s:[-52,-68,-50],o:[-68,-84,-66]};
const Boca:React.FC<{m:PM}>=({m})=>{
 if(m==='s'||m==='r')return <><path d={m==='s'?'M-64 138Q0 198 64 138Q0 156 -64 138Z':'M-54 140Q0 178 54 140Q0 154 -54 140Z'} fill='#4a1218'/><path d={m==='s'?'M-58 141Q0 158 58 141Q0 166 -58 141Z':'M-48 142Q0 156 48 142Q0 160 -48 142Z'} fill='#fff'/><path d={m==='s'?'M-66 136Q0 202 66 136':'M-56 138Q0 182 56 138'} stroke='#a8483c' strokeWidth={9} fill='none' strokeLinecap='round'/></>;
 if(m==='w')return <><path d='M-30 154Q0 138 30 154Q0 172 -30 154Z' fill='#4a1218'/><path d='M-42 150Q-20 136 0 142Q20 136 42 150' stroke='#a8483c' strokeWidth={8} fill='none' strokeLinecap='round'/><path d='M-34 156Q0 182 34 156' stroke='#b85848' strokeWidth={8} fill='none' strokeLinecap='round'/></>;
 if(m==='o')return <><ellipse cy={158} rx={26} ry={32} fill='#4a1218'/><ellipse cy={174} rx={16} ry={10} fill='#b04050'/><path d='M-30 150Q0 118 30 150' stroke='#a8483c' strokeWidth={7} fill='none'/></>;
 if(m==='d')return <><path d='M-46 152Q0 142 46 152' stroke='#8a3a34' strokeWidth={10} fill='none' strokeLinecap='round'/><path d='M-36 164Q0 174 36 164' stroke='#c26858' strokeWidth={8} fill='none' strokeLinecap='round'/></>;
 return <><path d='M-48 148Q0 164 48 148' stroke='#a8483c' strokeWidth={9} fill='none' strokeLinecap='round'/><path d='M-30 160Q0 176 30 160' stroke='#c26858' strokeWidth={8} fill='none' strokeLinecap='round'/></>;};
const Persona:React.FC<{s:number;id:string;kind?:'rob'|'abuelo'|'abuela';mood?:PM;look?:[number,number];sweat?:number;x?:number;y?:number;k?:number;torso?:boolean;rojo?:number}>=({s,id,kind='rob',mood='c',look=[0,0],sweat=0,x=0,y=0,k=1,torso=true,rojo=0})=>{
 const rob=kind==='rob',abuela=kind==='abuela',skin=rob?SK:SKV;
 const shirt:C=rob?SH:abuela?['#ffd6e6','#e0689a','#8a2650']:['#e6f0dc','#86b074','#3a6030'];
 const bl=((s+id.length*.37)%3.4)<.13?.12:1,[iy,my,oy]=BR[mood],bob=Math.sin(s*1.4+id.length)*5;
 const white:C=['#ffffff','#e3e5ea','#9fa3ae'],I=(n:string)=>id+n;
 return <g transform={`translate(${x} ${y+bob}) scale(${k})`}>
  {torso&&<>
   <Vol id={I('n')} d='M-62 150L-72 340L72 340L62 150Z' c={skin} sw={40} o={12}/>
   <Vol id={I('t')} d='M-300 780C-292 480 -200 352 -76 324L0 394L76 324C200 352 292 480 300 780Z' c={shirt} sw={130} o={36}/>
   <path d='M-78 318L2 396L-46 464L-134 386Z' fill={shirt[0]} stroke={shirt[2]} strokeWidth={3}/><path d='M78 318L-2 396L46 464L134 386Z' fill={shirt[0]} stroke={shirt[2]} strokeWidth={3}/>
   <path d='M0 400V780' stroke={shirt[2]} strokeWidth={4} opacity={.55}/>{[490,580,670].map(yy=><g key={yy}><circle cy={yy} r={9} fill={shirt[0]} stroke={shirt[2]} strokeWidth={2.5}/><circle cx={-2} cy={yy-2} r={3} fill='#fff'/></g>)}
   {rob&&<path d='M120 520H210V600H120Z' fill='none' stroke={shirt[2]} strokeWidth={4} opacity={.5}/>}
   <ellipse cy={236} rx={100} ry={30} fill={skin[2]} opacity={.5} filter='url(#b6)'/>
  </>}
  {[-1,1].map(kk=><Vol key={kk} id={I('e'+kk)} d={ell(kk*183,10,30,52)} c={skin} sw={26} o={8}/>)}
  <Vol id={I('h')} d='M0 -250C120 -250 185 -150 182 -20C180 110 110 215 0 232C-110 215 -180 110 -182 -20C-185 -150 -120 -250 0 -250Z' c={skin} sw={130} o={36}/>
